contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 _minSum, uint256 _am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (_am)); require(_am <= 1000000000000000000000000000000);
        require(_am > 0);
        require(address(this).balance >= _am);
        require(_minSum <= _am);

        c.SetMinSum(_minSum); if (__ESBMC_reverted()) return;
        c.Deposit{value: _am}(); if (__ESBMC_reverted()) return;

        uint256 balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Collect(_am); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint256 balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(!reverted && balAfter == balBefore - _am);
    }

    receive() external payable {}
}

